import { Syne, Noto_Sans_KR } from "next/font/google";

/**
 * PRISM GLAZE 프리즘 글레이즈 — a liquid-glass house. The voice is a poured
 * glaze: cool, refractive, a little syrupy. Syne — a sharp, slightly quirky
 * geometric display whose hairline-to-bold range reads like a bevel; the
 * wordmark and kickers. Noto Sans KR (300/500) — the calm Hangul weights that
 * sit cleanly behind a glass panel.
 *
 * styles.css consumes these as var(--font-syne) / var(--font-noto-sans-kr);
 * page.tsx applies the .variable classes on the entry root.
 */
export const syne = Syne({
  weight: ["400", "600", "700", "800"],
  subsets: ["latin"],
  variable: "--font-syne",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["300", "400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { syne, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "PRISM GLAZE";
const CHIPS = [
  { ko: "굴절률 1.52", en: "Refractive index 1.52" },
  { ko: "두께 0.4mm", en: "Thickness 0.4mm" },
  { ko: "오로라 워시", en: "Aurora wash" },
  { ko: "스펙큘러 트래킹", en: "Specular tracking" },
];

/**
 * PRISM GLAZE 프리즘 글레이즈 — a liquid-glass house. The signature is a panel
 * material: backdrop-filter glass over a drifting aurora wash, with a specular
 * highlight that follows the pointer (the surface is a lens that remembers
 * light). The wordmark is a beveled glass cut — hairline above, bold below,
 * split per glyph and revealed on scroll.
 *
 * `.prism-glaze-js` is added on mount so the no-JS markup is the finished
 * page: panels are solid, the aurora is a static gradient, the wordmark sits.
 */
export default function PrismGlazePage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("prism-glaze-js");
    // Defer one frame so the glyph pre-state (opacity 0) applies before reveal.
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "prism-glaze" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Specular highlight: write the pointer position as CSS vars on the stage
  // so each glass panel's ::before highlight follows the cursor. Lerped +
  // gated off under reduced motion (the highlight then sits top-left, static).
  useEffect(() => {
    if (reduced) return;
    const stage = stageRef.current;
    if (!stage) return;
    let raf = 0;
    let tx = 0.3;
    let ty = 0.25;
    let cx = tx;
    let cy = ty;
    const onMove = (e: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      tx = (e.clientX - r.left) / r.width;
      ty = (e.clientY - r.top) / r.height;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      cx += (tx - cx) * 0.12;
      cy += (ty - cy) * 0.12;
      stage.style.setProperty("--pg-x", cx.toFixed(3));
      stage.style.setProperty("--pg-y", cy.toFixed(3));
      if (Math.abs(tx - cx) > 0.001 || Math.abs(ty - cy) > 0.001) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${syne.variable} ${notoSansKR.variable} prism-glaze-root`}
    >
      <div ref={revealRef} className="prism-glaze-doc">
        <header className="prism-glaze-hero">
          <div className="prism-glaze-aurora" aria-hidden="true" />
          <p className="prism-glaze-kicker">
            <span lang="ko">액체 유리 하우스</span> · LIQUID GLASS HOUSE · 서울
          </p>
          <h1 className="prism-glaze-title" aria-label={TITLE}>
            {TITLE.split("").map((ch, i) => (
              <span
                key={i}
                aria-hidden="true"
                className={ch === " " ? "prism-glaze-glyph prism-glaze-glyph--space" : "prism-glaze-glyph"}
                style={{ "--pg-i": i } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </h1>
          <p className="prism-glaze-title__ko" lang="ko">프리즘 글레이즈</p>
          <p className="prism-glaze-sub">
            <span lang="ko">유리를 붓듯.</span> Glass, poured.
          </p>
        </header>

        <main>
          <section ref={stageRef} className="prism-glaze-stage" data-reveal>
            <article className="prism-glaze-panel prism-glaze-panel--lg">
              <h2 className="prism-glaze-panel__h">
                <span lang="ko">빛을 굴절하는 패널.</span> A panel that bends light.
              </h2>
              <p className="prism-glaze-panel__p">
                <span lang="ko">
                  면 위를 흐르는 오로라 워시. 포인터를 따라 움직이는 하이라이트.
                  패널은 렌즈다 — 보는 각도마다 다른 색.
                </span>{" "}
                An aurora wash drifts across the surface; a highlight tracks the
                pointer. The panel is a lens — a different color at every angle.
              </p>
            </article>

            <div className="prism-glaze-grid">
              {CHIPS.map((c, i) => (
                <article
                  key={i}
                  className="prism-glaze-panel prism-glaze-panel--chip"
                  style={{ "--pg-d": i * 90 } as CSSProperties}
                >
                  <span className="prism-glaze-chip__en">{c.en}</span>
                  <span className="prism-glaze-chip__ko" lang="ko">{c.ko}</span>
                </article>
              ))}
            </div>
          </section>

          <section className="prism-glaze-lead" data-reveal>
            <p className="prism-glaze-lead__p">
              <span lang="ko">
                우리는 인터페이스를 재료로 생각한다 — 두께, 굴절률, 빛. 화면을
                유리로 부어, 손가락이 닿는 자리마다 작은 무지개가 인다.
              </span>{" "}
              We think of interface as material — thickness, index, light. We pour
              the screen as glass, and where a finger lands, a small rainbow blooms.
            </p>
          </section>
        </main>

        <footer className="prism-glaze-foot">
          <span>PRISM GLAZE · 2026</span>
          <span lang="ko">프리즘 글레이즈 — 서울 성수</span>
        </footer>
      </div>
    </div>
  );
}

.prism-glaze-root {
  --pg-bg: #060912;
  --pg-deep: #02040a;
  --pg-text: #eaf6ff;
  --pg-mute: #8fb2c9;
  --pg-cyan: #7fdfff;
  --pg-violet: #b78bff;
  --pg-aqua: #54f0d0;
  --pg-font-display: var(--font-syne), "Syne", system-ui, sans-serif;
  --pg-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --pg-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --pg-x: 0.3;
  --pg-y: 0.25;

  min-height: 100vh;
  margin: 0;
  background: var(--pg-bg);
  color: var(--pg-text);
  font-family: var(--pg-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

.prism-glaze-doc {
  position: relative;
  max-width: 1240px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

.prism-glaze-root ::selection {
  background: var(--pg-cyan);
  color: var(--pg-deep);
}

/* ---- Aurora wash (the field every panel refracts) ---- */
.prism-glaze-aurora {
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(40% 50% at 18% 28%, rgba(127, 223, 255, 0.42), transparent 70%),
    radial-gradient(38% 46% at 82% 22%, rgba(183, 139, 255, 0.40), transparent 70%),
    radial-gradient(46% 52% at 60% 82%, rgba(84, 240, 208, 0.34), transparent 72%),
    radial-gradient(50% 60% at 12% 78%, rgba(255, 122, 196, 0.26), transparent 72%);
  filter: blur(40px) saturate(1.2);
  opacity: 0.9;
  animation: pg-drift 26s var(--pg-ease) infinite alternate;
}
@keyframes pg-drift {
  0% { transform: translate3d(-3%, -2%, 0) scale(1.05); }
  100% { transform: translate3d(4%, 3%, 0) scale(1.12); }
}
@media (prefers-reduced-motion: reduce) {
  .prism-glaze-aurora { animation: none; }
}

/* ---- Hero ---- */
.prism-glaze-hero {
  position: relative;
  z-index: 1;
  padding: clamp(4rem, 14vh, 10rem) 0 2rem;
}
.prism-glaze-kicker {
  margin: 0 0 1.5rem;
  font-family: var(--pg-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 600;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--pg-cyan);
}
.prism-glaze-title {
  margin: 0;
  font-family: var(--pg-font-display);
  font-weight: 800;
  font-size: clamp(2.8rem, 11vw, 8.5rem);
  line-height: 0.92;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  /* beveled glass cut: a bright top edge + a deep drop, like a cut crystal */
  color: #f4fbff;
  text-shadow:
    0 1px 0 rgba(255, 255, 255, 0.85),
    0 -1px 0 rgba(127, 223, 255, 0.6),
    0 6px 24px rgba(127, 223, 255, 0.28),
    0 2px 4px rgba(2, 4, 10, 0.7);
}
.prism-glaze-glyph {
  display: inline-block;
}
.prism-glaze-glyph--space { width: 0.28em; }
.prism-glaze-title__ko {
  margin: 0.5rem 0 0;
  font-family: var(--pg-font-kr);
  font-weight: 300;
  font-size: clamp(1.1rem, 3vw, 2rem);
  letter-spacing: 0.32em;
  color: var(--pg-mute);
}
.prism-glaze-sub {
  margin: 1.4rem 0 0;
  font-size: clamp(1rem, 1.8vw, 1.3rem);
  font-weight: 400;
  color: var(--pg-text);
}
.prism-glaze-sub span[lang="ko"] { color: var(--pg-mute); margin-right: 0.5rem; }

/* ---- Glass panel material ---- */
.prism-glaze-panel {
  position: relative;
  z-index: 1;
  border-radius: 22px;
  padding: clamp(1.4rem, 3vw, 2.2rem);
  background: rgba(18, 30, 48, 0.34);
  border: 1px solid rgba(180, 220, 255, 0.16);
  backdrop-filter: blur(22px) saturate(1.4);
  -webkit-backdrop-filter: blur(22px) saturate(1.4);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    inset 0 -1px 0 rgba(127, 223, 255, 0.1),
    0 30px 60px -28px rgba(2, 6, 16, 0.8);
  overflow: hidden;
}
/* Specular highlight that tracks the pointer via --pg-x/--pg-y. */
.prism-glaze-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    38% 60% at calc(var(--pg-x) * 100%) calc(var(--pg-y) * 100%),
    rgba(255, 255, 255, 0.32),
    rgba(127, 223, 255, 0.12) 38%,
    transparent 70%
  );
  opacity: 0.85;
  pointer-events: none;
  transition: opacity 600ms var(--pg-ease);
}
/* A faint refraction edge that also drifts with the pointer. */
.prism-glaze-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    135deg,
    rgba(127, 223, 255, 0.55),
    transparent 40%,
    transparent 60%,
    rgba(183, 139, 255, 0.45)
  );
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.prism-glaze-stage {
  position: relative;
  z-index: 1;
  margin: clamp(2.5rem, 6vw, 4.5rem) 0;
  display: flex;
  flex-direction: column;
  gap: clamp(1rem, 2vw, 1.5rem);
}
.prism-glaze-panel--lg { min-height: 220px; }
.prism-glaze-panel__h {
  margin: 0 0 0.8rem;
  font-family: var(--pg-font-display);
  font-weight: 700;
  font-size: clamp(1.3rem, 2.6vw, 2rem);
  letter-spacing: -0.01em;
}
.prism-glaze-panel__h span[lang="ko"] {
  display: block;
  font-family: var(--pg-font-kr);
  font-weight: 500;
  color: var(--pg-cyan);
  font-size: 0.74em;
  margin-bottom: 0.3em;
}
.prism-glaze-panel__p {
  margin: 0;
  max-width: 60ch;
  color: var(--pg-mute);
  font-size: clamp(0.96rem, 1.4vw, 1.1rem);
}
.prism-glaze-panel__p span[lang="ko"] { color: var(--pg-text); }

.prism-glaze-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
}
.prism-glaze-panel--chip {
  padding: clamp(1.1rem, 2vw, 1.5rem);
  min-height: 140px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.4rem;
}
.prism-glaze-chip__en {
  font-family: var(--pg-font-display);
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--pg-text);
}
.prism-glaze-chip__ko {
  font-size: 0.86rem;
  color: var(--pg-mute);
  letter-spacing: 0.04em;
}

.prism-glaze-lead {
  position: relative;
  z-index: 1;
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(127, 223, 255, 0.14);
}
.prism-glaze-lead__p {
  margin: 0 auto;
  max-width: 64ch;
  font-family: var(--pg-font-display);
  font-weight: 400;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
  color: var(--pg-text);
}
.prism-glaze-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--pg-font-kr);
  color: var(--pg-mute);
  font-size: 0.72em;
  margin-bottom: 0.6em;
}

.prism-glaze-foot {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(127, 223, 255, 0.14);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--pg-mute);
  font-family: var(--pg-font-display);
}

/* ---- Reveal gating ---- */
.prism-glaze-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--pg-ease), transform 800ms var(--pg-ease);
}
.prism-glaze-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}
/* Glyph-by-glyph reveal of the wordmark. */
.prism-glaze-js .prism-glaze-glyph {
  opacity: 0;
  transform: translateY(0.3em) rotate(4deg);
  display: inline-block;
  transition:
    opacity 600ms var(--pg-ease),
    transform 700ms var(--pg-ease);
  transition-delay: calc(var(--pg-i) * 60ms + 200ms);
}
.prism-glaze-js.is-mounted .prism-glaze-glyph,
.prism-glaze-js .prism-glaze-title.is-visible .prism-glaze-glyph {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .prism-glaze-js [data-reveal],
  .prism-glaze-js .prism-glaze-glyph {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

.prism-glaze-root :focus-visible {
  outline: 2px solid var(--pg-cyan);
  outline-offset: 3px;
}
